from pathlib import Path
p=Path('src/App.tsx')
s=p.read_text()
old='''    <p className="muted">Lv {monster.level} · {monster.rank} · {monster.species}{monster.combatStyle ? ` · ${monster.combatStyle}` : ''}</p>\n    <div className="stats"><b>HP {monster.hp}</b><b>Crisis {monster.crisis ?? Math.floor(monster.hp/2)}</b><b>MP {monster.mp}</b><b>Init {monster.initiative}</b><b>DEF {monster.defense}</b><b>M.DEF {monster.magicDefense}</b><b>Turns {monster.turnsPerRound || 1}</b></div>\n    <div className="dice"><span>DEX d{monster.attributes.dex}</span><span>INS d{monster.attributes.ins}</span><span>MIG d{monster.attributes.mig}</span><span>WLP d{monster.attributes.wlp}</span><span>ACC +{monster.accuracyBonus ?? Math.floor(monster.level/10)}</span><span>MAG +{monster.magicBonus ?? Math.floor(monster.level/10)}</span></div>\n    <p><strong>Traits:</strong> {(monster.traits || []).join(', ')}</p><div className="affinities">{damageTypes.filter(t=>affinities[t] !== 'Normal').map(t=><span key={t}>{t}: {affinities[t]}</span>)}</div>\n    <div className="tacticsBox"><strong>Tactics — {style}</strong><span>{combatTactics[style]}</span></div><h3>Basic Attacks</h3>'''
new='''    <div className="monsterIdentity"><span>LV <b>{monster.level}</b></span><span>{monster.rank}</span><span>{monster.species}</span><span>{style}</span></div>\n    <div className="monsterVitals"><div className="vital hp"><span>HP</span><strong>{monster.hp}</strong><small>Crisis {monster.crisis ?? Math.floor(monster.hp/2)}</small></div><div className="vital mp"><span>MP</span><strong>{monster.mp}</strong></div><div className="vital"><span>DEF</span><strong>{monster.defense}</strong></div><div className="vital"><span>M.DEF</span><strong>{monster.magicDefense}</strong></div><div className="vital"><span>INIT</span><strong>{monster.initiative}</strong></div><div className="vital"><span>TURN</span><strong>{monster.turnsPerRound || 1}</strong></div></div>\n    <div className="monsterAttributes"><span><b>DEX</b> d{monster.attributes.dex}</span><span><b>INS</b> d{monster.attributes.ins}</span><span><b>MIG</b> d{monster.attributes.mig}</span><span><b>WLP</b> d{monster.attributes.wlp}</span><span><b>ACC</b> +{monster.accuracyBonus ?? Math.floor(monster.level/10)}</span><span><b>MAG</b> +{monster.magicBonus ?? Math.floor(monster.level/10)}</span></div>\n    <div className="monsterTraits"><strong>Traits</strong><span>{(monster.traits || []).join(' · ')}</span></div>\n    <div className="affinityBlock"><div className="sectionLabel">Affinities</div><div className="affinityGrid">{damageTypes.map(t=><span key={t} className={`affinityChip affinity-${String(affinities[t]).toLowerCase()}`}><b>{t}</b><small>{affinities[t]}</small></span>)}</div></div>\n    <div className="tacticsBox"><strong>Tactics — {style}</strong><span>{combatTactics[style]}</span></div><h3 className="combatHeading">Attacks</h3>'''
if old not in s: raise SystemExit('monster display block not found')
s=s.replace(old,new,1)
old='''    {notes.length > 0 && <details><summary>Rules / generation notes</summary>{notes.map((n,i)=><p className="note" key={i}>{n}</p>)}</details>}'''
new='''    {notes.length > 0 && <details className="monsterLore"><summary>Aestra lore & design notes</summary><div className="lorePanel">{notes.map((n,i)=><p className="note" key={i}>{n}</p>)}</div></details>}'''
if old not in s: raise SystemExit('notes block not found')
s=s.replace(old,new,1)
p.write_text(s)

p=Path('src/styles.css')
s=p.read_text()
anchor='.monsterCard h3 { margin-top: 18px; }'
css='''.monsterCard h3 { margin-top: 18px; }\n.monsterIdentity { display:flex; flex-wrap:wrap; gap:6px; margin:10px 0 12px; }\n.monsterIdentity span { padding:4px 8px; border:1px solid #435650; background:#0b1919; color:#cfc8b8; font-size:.78rem; text-transform:uppercase; letter-spacing:.06em; }\n.monsterIdentity span:first-child { border-color:var(--brass); color:var(--brass-bright); }\n.monsterVitals { display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); gap:6px; margin:12px 0; }\n.vital { min-height:70px; display:grid; place-items:center; align-content:center; border:1px solid #40534f; background:linear-gradient(180deg,#102120,#091616); text-align:center; }\n.vital span { color:#9da9a3; font-size:.67rem; letter-spacing:.12em; font-weight:800; }\n.vital strong { color:#f0e7d2; font-size:1.45rem; line-height:1.1; }\n.vital small { color:#d4a98e; font-size:.68rem; margin-top:2px; }\n.vital.hp { border-color:#76594e; } .vital.mp { border-color:#3f6d68; }\n.monsterAttributes { display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); gap:5px; margin:8px 0 12px; }\n.monsterAttributes span { padding:6px 4px; text-align:center; border:1px solid #314541; background:rgba(8,18,19,.72); font-size:.82rem; }\n.monsterAttributes b { color:var(--crystal); font-size:.68rem; margin-right:3px; }\n.monsterTraits { display:grid; grid-template-columns:auto 1fr; gap:10px; padding:9px 10px; border-left:3px solid var(--brass); background:rgba(195,167,108,.07); margin:10px 0 13px; }\n.monsterTraits strong { color:var(--brass-bright); } .monsterTraits span { color:#d5cebd; }\n.sectionLabel { color:#aeb7af; text-transform:uppercase; letter-spacing:.14em; font-size:.68rem; font-weight:800; margin-bottom:6px; }\n.affinityGrid { display:grid; grid-template-columns:repeat(9,minmax(0,1fr)); gap:4px; margin-bottom:13px; }\n.affinityChip { display:grid; gap:1px; padding:5px 3px; text-align:center; border:1px solid #354844; background:#0a1718; min-width:0; }\n.affinityChip b { text-transform:uppercase; font-size:.61rem; overflow:hidden; text-overflow:ellipsis; } .affinityChip small { font-size:.62rem; color:#aab2ab; }\n.affinity-vulnerable { border-color:#925f52; background:rgba(125,57,45,.16); } .affinity-vulnerable small { color:#e5a38f; }\n.affinity-resistant { border-color:#617653; background:rgba(79,105,65,.15); } .affinity-resistant small { color:#bad2a6; }\n.affinity-immune { border-color:#52716d; background:rgba(65,111,105,.16); } .affinity-immune small { color:#a8ded4; }\n.affinity-absorb { border-color:#796a96; background:rgba(95,74,128,.16); } .affinity-absorb small { color:#cbb8e8; }\n.combatHeading { padding-bottom:5px; border-bottom:1px solid rgba(195,167,108,.28); text-transform:uppercase; letter-spacing:.08em; font-size:1rem; }\n.monsterLore { margin-top:16px; border:1px solid #3c4d49; background:rgba(6,15,16,.5); padding:9px 10px; } .monsterLore summary { color:#bdb397; } .lorePanel { margin-top:8px; display:grid; gap:6px; } .lorePanel .note { margin:0; font-size:.86rem; }'''
if anchor not in s: raise SystemExit('css anchor missing')
s=s.replace(anchor,css,1)
s=s.replace('''  .cardTitle { flex-wrap: wrap; }''','''  .cardTitle { flex-wrap: wrap; }\n  .monsterVitals { grid-template-columns:repeat(3,minmax(0,1fr)); }\n  .monsterAttributes { grid-template-columns:repeat(3,minmax(0,1fr)); }\n  .affinityGrid { grid-template-columns:repeat(3,minmax(0,1fr)); }''',1)
p.write_text(s)
